import fs from 'fs';
import path from 'path';

const logsDir = 'C:/Users/U-ser/.gemini/antigravity/brain/a812c987-f1b1-470b-8001-05e402a20838/.system_generated/logs/chunks/transcript_full';

if (fs.existsSync(logsDir)) {
  const files = fs.readdirSync(logsDir).filter(f => f.endsWith('.jsonl'));
  for (const file of files) {
    const content = fs.readFileSync(path.join(logsDir, file), 'utf8');
    if (content.includes('questionID') || content.includes('questionText')) {
      console.log(`Found question content in file: ${file}`);
      const lines = content.split('\n');
      lines.forEach((line, idx) => {
        if (line.includes('questionID') && line.includes('USER_INPUT')) {
          console.log(`  Line ${idx} in ${file} has USER_INPUT with questionID!`);
          fs.writeFileSync(`d:/passkru/PassKru/server/raw_user_payload_${file}.json`, line);
        }
      });
    }
  }
}
